style.css:
@-moz-document domain("roblox.com") {
:root {
    --main-bg: #0a0a0a;
    --main-text: #e0e0e0;
    --accent-blue: #00bfff;
    --hover-blue: #007acc;
    --card-bg: #121212;
  }

  body {
    background-color: var(--main-bg) !important;
    color: var(--main-text) !important;
    transition: all 0.3s ease-in-out;
  }

  a, a:visited {
    color: var(--accent-blue) !important;
    transition: color 0.2s ease-in-out;
  }

  a:hover {
    color: var(--hover-blue) !important;
  }

  .game-card-container, .card-item, .game-card, .section, .rbx-navbar, .rbx-header, .rbx-footer, .rbx-body, .container-header, .content {
    background-color: var(--card-bg) !important;
    border-radius: 10px;
    box-shadow: 0 0 15px rgba(0,191,255,0.1);
    transition: background-color 0.3s ease-in-out;
  }

  .btn-primary, .btn-secondary {
    background-color: var(--accent-blue) !important;
    border: none !important;
    color: #ffffff !important;
    transition: background-color 0.2s ease-in-out;
  }

  .btn-primary:hover, .btn-secondary:hover {
    background-color: var(--hover-blue) !important;
  }

  .input-field, input, textarea, select {
    background-color: #1a1a1a !important;
    color: var(--main-text) !important;
    border: 1px solid var(--accent-blue) !important;
    border-radius: 6px;
  }

  ::selection {
    background: var(--accent-blue);
    color: #fff;
  }

  .game-name, .text-label, .font-header-2, .font-caption-header {
    color: var(--accent-blue) !important;
  }

  .tooltip, .dropdown-menu {
    background-color: #1c1c1c !important;
    color: var(--main-text) !important;
    border: 1px solid var(--hover-blue) !important;
  }

  /* Smooth everything */
  * {
    transition: background-color 0.2s ease-in-out, color 0.2s ease-in-out, border 0.2s ease-in-out;
  }
}
